glsl3.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 color;
in vec2 uv0;
uniform sampler2D cc_spriteTexture;
uniform sampler2D flowTexture;
layout(std140) uniform DefensePoseFlow {
  vec4 frameA;
  vec4 frameB;
  vec4 frameC;
  vec4 poseWeights;
  vec4 pairSlots;
  vec4 flowInfo;
  vec4 flowAtlas;
  vec4 captainOutline;
};
vec4 motion(vec2 point,float slot) {
  if(abs(slot)<0.5)return vec4(0.0);
  vec2 p=clamp(point,vec2(0.0),vec2(1.0));
  vec2 sampleUV=(p*(flowInfo.zw-vec2(1.0))+vec2(0.5,0.5+(abs(slot)-1.0)*flowInfo.w))/flowAtlas.xy;
  vec4 field=(texture(flowTexture,sampleUV)*255.0-128.0)/127.0;
  field*=flowInfo.xyxy;
  return slot>0.0?field:field.zwxy;
}
vec4 source(vec2 point,vec4 rect) {
  float inside=step(0.0,point.x)*step(point.x,1.0)*step(0.0,point.y)*step(point.y,1.0);
  vec2 margin=vec2(0.5)/flowAtlas.zw;
  vec4 pixel=CCSampleWithAlphaSeparated(cc_spriteTexture,rect.xy+clamp(point,margin,vec2(1.0)-margin)*rect.zw);
  pixel.a*=inside;pixel.rgb*=pixel.a;return pixel;
}
vec4 frag () {
  vec2 p=(uv0-frameA.xy)/frameA.zw;
  vec2 pa=p,pb=p,pc=p;
  for(int i=0;i<2;i++) {
    pa=p-poseWeights.y*motion(pa,pairSlots.x).xy-poseWeights.z*motion(pa,pairSlots.y).xy;
    pb=p-poseWeights.x*motion(pb,pairSlots.x).zw-poseWeights.z*motion(pb,pairSlots.z).xy;
    if(poseWeights.z>0.0001)pc=p-poseWeights.x*motion(pc,pairSlots.y).zw-poseWeights.y*motion(pc,pairSlots.z).zw;
  }
  vec4 pixel=source(pa,frameA)*poseWeights.x+source(pb,frameB)*poseWeights.y;
  if(poseWeights.z>0.0001)pixel+=source(pc,frameC)*poseWeights.z;
  if(captainOutline.z>0.5) {
    float edge=pixel.a;
    for(int i=0;i<8;i++) {
      vec2 direction=vec2(1.0,0.0);
      if(i==1)direction=vec2(-1.0,0.0);
      if(i==2)direction=vec2(0.0,1.0);
      if(i==3)direction=vec2(0.0,-1.0);
      if(i==4)direction=vec2(0.70710678,0.70710678);
      if(i==5)direction=vec2(-0.70710678,0.70710678);
      if(i==6)direction=vec2(0.70710678,-0.70710678);
      if(i==7)direction=vec2(-0.70710678,-0.70710678);
      vec2 offset=direction*captainOutline.xy;
      float alpha=source(pa+offset,frameA).a*poseWeights.x+source(pb+offset,frameB).a*poseWeights.y;
      if(poseWeights.z>0.0001)alpha+=source(pc+offset,frameC).a*poseWeights.z;
      edge=max(edge,alpha);
    }
    float rim=max(edge-pixel.a,0.0)*(1.0-pixel.a);
    pixel.rgb+=vec3(rim);pixel.a+=rim;
  }
  pixel.rgb/=max(pixel.a,0.00001);
  vec4 outputColor=pixel*color;ALPHA_TEST(outputColor);return outputColor;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

